Introduced a new test file src/components/__tests__/ValuePropositionSection.test.tsx.
The test verifies:
The headline and sub‑head render correctly.
All four FeatureCard titles and descriptions are present.
Each card’s icon renders (mocked via lucide-react to keep the test fast).
Utilized Jest/Vitest and React Testing Library for assertions.
Mocked lucide-react icons to avoid heavy SVG imports and potential worker timeouts.
Updated test logic to use screen.getAllByText for robust matching of description strings.
Implementation Details
Test File:
tsx
import React from 'react';
import { render, screen } from '@testing-library/react';
import ValuePropositionSection from '../ValuePropositionSection';
import { vi } from 'vitest';
// Mock lucide-react icons
vi.mock('lucide-react', () => ({
  Clock: () => <svg data-testid="icon" />,
  Settings: () => <svg data-testid="icon" />,
  PauseCircle: () => <svg data-testid="icon" />,
  Star: () => <svg data-testid="icon" />,
}));
describe('ValuePropositionSection', () => {
  test('renders headline, subhead and all feature cards', () => {
    render(<ValuePropositionSection />);
    // Headline & subhead
    expect(
      screen.getByRole('heading', { level: 2, name: /Treasury streaming infrastructure/i })
    ).toBeInTheDocument();
    expect(
      screen.getByText(/Everything you need to manage continuous capital flow on Stellar/i)
    ).toBeInTheDocument();
    // Feature card titles
    const titles = [
      'Real-time USDC streaming',
      'Configurable rate & cliff',
      'Pause and cancel controls',
      'Built on Stellar & Soroban',
    ];
    titles.forEach((title) => {
      expect(screen.getByRole('heading', { level: 3, name: title })).toBeInTheDocument();
    });
    // Feature card descriptions (partial match)
    const descriptions = [
      'Funds accrue per second; recipients withdraw anytime',
      'Set streaming rate, start/end timestamps, and optional cliff periods',
      'Treasury or admin can pause or cancel active streams',
      'Native Stellar infrastructure. Soroban smart contracts',
    ];
    descriptions.forEach((desc) => {
      const matches = screen.getAllByText((content, element) =>
        element?.textContent?.includes(desc)
      );
      expect(matches.length).toBeGreaterThan(0);
    });
    // Icons (4 mocked svgs)
    expect(screen.getAllByTestId('icon')).toHaveLength(4);
  });
});
